<body>
<main>
<header><div><div class="eyebrow">CIS 223 · BST · Java step-by-step</div><h1>Delete · Successor 对照演示</h1></div>
<div class="tabs" role="tablist" aria-label="选择 Successor 类型"><button class="tab" id="tab-direct" role="tab" aria-selected="true">Direct Successor</button><button class="tab" id="tab-deep" role="tab" aria-selected="false">Deep Successor</button></div></header>
<p id="subtitle">Direct：y == z.right；只需要一次 transplant</p>
<section class="card"><div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:11px"><h2 id="stepTitle">Before · 原始 BST</h2><span id="counter">Step 1 / 7</span></div>
<div class="layout">
<div class="diagram"><svg id="tree" viewBox="0 0 940 515" role="img" aria-label="Binary search tree deletion interactive diagram"><g id="background"></g><g id="links"></g><g id="nodes"></g><g id="labels"></g></svg>
<div class="legend"><span style="--dot:#2563eb">z · 被删除的 Node</span><span style="--dot:#d97706">y · Successor</span><span style="--dot:#159f73">本步改变的 Reference</span><span style="--dot:#9aaec1">其余 Node</span></div>
<div class="explain"><strong id="desc">选择模式，点击下一步</strong><div id="change"></div></div>
<div class="inspect" id="inspect">点击图中任何 Node，查看它当前的 left / right / p。</div>
</div>
<div><h2>Java · 当前执行行</h2><div id="code" class="code" aria-live="polite"></div>
<div class="methods"><div><b>transplant 次数</b><code id="calls">0 / 1</code></div><div><b>当前 Root / Successor</b><code id="rootInfo">root=20 · y=30</code></div></div>
<div class="help">被跳过的代码以删除线标出。树图的实线表示从当前 root 可到达的 Child Reference；虚线表示暂时脱离主树的旧引用。</div>
</div></div>
<div class="controls"><button class="ctrl" id="prev">← 上一步</button><input id="slider" type="range" min="0" max="6" step="1" value="0" aria-label="选择运行步骤"><button class="ctrl primary" id="next">下一步 →</button><button class="ctrl" id="reset">重置</button></div></section>
</main>
<script>
(function(){
'use strict';
const NS='http://www.w3.org/2000/svg';let mode='direct',step=0,selected=null;
const method=[
'public void delete(Node z) {',
'    if (z.left == null) {',
'        transplant(z, z.right);',
'    } else if (z.right == null) {',
'        transplant(z, z.left);',
'    } else {',
'        Node y = minimum(z.right);',
'        if (y.p != z) {',
'            transplant(y, y.right);',
'            y.right = z.right;',
'            y.right.p = y;',
'        }',
'        transplant(z, y);',
'        y.left = z.left;',
'        y.left.p = y;',
'    }',
'}'];
const examples={
direct:{
 name:'Direct Successor',sub:'Direct：y == z.right；只需要一次 transplant',z:20,y:30,initial:{root:20,nodes:{20:{l:10,r:30,p:null},10:{l:5,r:15,p:20},5:{l:null,r:null,p:10},15:{l:null,r:null,p:10},30:{l:null,r:40,p:20},40:{l:null,r:null,p:30}}},
 steps:[
 {title:'Before · 两个孩子',desc:'准备删除 z = 20。它有左孩子 10 和右孩子 30，因此前两个 if 都不成立。',change:'z.left = 10   ·   z.right = 30',line:1,calls:0},
 {title:'Find Successor',desc:'从 z.right = 30 开始沿左边找 minimum，30.left 为 null，所以 y = 30。',change:'y = minimum(20.right) = 30',line:6,calls:0},
 {title:'Direct · 跳过 Deep 专用代码',desc:'y.p = 20 = z，if (y.p != z) 为 false。右子树原本就属于 30，不要重新执行 y.right = z.right，否则会形成 y.right = y。',change:'y.p == z   →   skip 3 Deep-only statements',line:7,calls:0},
 {title:'transplant(z, y)',desc:'把 30 放到 20 原来的 Root 位置。原左子树 10 尚未接回；暂时可以看到旧的 z 分支。',change:'root: 20 → 30   ·   30.p: 20 → null',line:12,calls:1,apply:s=>{s.root=30;s.nodes[30].p=null;}},
 {title:'Reconnect Left',desc:'30.left = 10。此时 10.p 还是 20，因此双向 Reference 尚未全部更新。',change:'30.left: null → 10   ·   10.p 仍为 20',line:13,calls:1,apply:s=>{s.nodes[30].l=10;}},
 {title:'Update Parent Pointer',desc:'将 10.p 改成 30，使它和 30.left 相互对应。',change:'10.p: 20 → 30',line:14,calls:1,apply:s=>{s.nodes[10].p=30;}},
 {title:'Done · 20 已离开 BST',desc:'完成！新 Root 为 30，10 与 40 都仍在树中。Node 20 仍可能被变量 z 引用，但不再属于 BST。',change:'root=30   ·   30.left=10   ·   10.p=30',line:16,calls:1}
 ],
 positions:s=>s<=2?{20:[415,78],10:[246,200],30:[620,200],5:[130,330],15:[340,330],40:[760,330]}:s===3?{20:[155,252],10:[205,343],30:[455,78],5:[110,447],15:[301,447],40:[650,213]}:{20:[840,425],10:[250,211],30:[455,78],5:[115,348],15:[365,348],40:[650,211]}
},
deep:{
 name:'Deep Successor',sub:'Deep：y.p != z；两次 transplant，先取出 y，再顶替 z',z:20,y:25,initial:{root:20,nodes:{20:{l:10,r:40,p:null},10:{l:null,r:null,p:20},40:{l:25,r:50,p:20},25:{l:null,r:27,p:40},27:{l:null,r:null,p:25},50:{l:null,r:null,p:40}}},
 steps:[
 {title:'Before · 两个孩子',desc:'准备删除 z = 20。左孩子 10，右孩子 40；两个孩子都存在。',change:'z.left=10   ·   z.right=40',line:1,calls:0},
 {title:'Find Successor',desc:'从 z.right = 40 沿 Left 找到 25：y=25。注意 25 有右孩子 27，所以不能把 27 丢掉。',change:'y=25   ·   y.p=40 ≠ z',line:6,calls:0},
 {title:'第一次 Transplant · 取出 25',desc:'transplant(25, 27) 用 27 顶替 25 原来的位置，同时更改 27.p。变量 y 仍指向 25。',change:'40.left:25→27   ·   27.p:25→40',line:8,calls:1,apply:s=>{s.nodes[40].l=27;s.nodes[27].p=40;}},
 {title:'重新接上原来的右子树',desc:'给 25 接上 20 的原右子树：25.right = 40。现在 25 还没有被安到 Root，40.p 暂时也没有更新。',change:'25.right:27→40   ·   40.p 仍为 20',line:9,calls:1,apply:s=>{s.nodes[25].r=40;}},
 {title:'Update Right Parent Pointer',desc:'将 40.p = 25，完成右子树的反向 Parent Pointer。接下来才替换 20。',change:'40.p:20→25',line:10,calls:1,apply:s=>{s.nodes[40].p=25;}},
 {title:'第二次 Transplant · 顶替 20',desc:'transplant(20, 25) 让 25 取代 20 成为 Root。此时旧左子树 10 尚未接入新 Root。',change:'root:20→25   ·   25.p:40→null',line:12,calls:2,apply:s=>{s.root=25;s.nodes[25].p=null;}},
 {title:'Reconnect Left',desc:'25.left = 10。此时 10.p 依然是旧的 20，还需要最后一行修正。',change:'25.left:null→10   ·   10.p 仍为 20',line:13,calls:2,apply:s=>{s.nodes[25].l=10;}},
 {title:'Done · 更新左孩子的 p',desc:'10.p = 25。完成后仍保留所有其他 Node；20 已从 BST 的可到达结构中移除。',change:'10.p:20→25   ·   root=25',line:14,calls:2,apply:s=>{s.nodes[10].p=25;}}
 ],
 positions:s=>s<=1?{20:[400,76],10:[220,207],40:[640,207],25:[540,333],27:[620,448],50:[785,333]}:s<=4?{20:[400,76],10:[220,207],40:[640,207],25:[865,452],27:[540,333],50:[785,333]}:s===5?{20:[185,323],10:[100,433],40:[640,207],25:[400,76],27:[540,333],50:[785,333]}:{20:[865,440],10:[220,207],40:[640,207],25:[400,76],27:[540,333],50:[785,333]}
}
};
function snapshot(example,n){const s=JSON.parse(JSON.stringify(example.initial));for(let i=0;i<=n;i++){if(example.steps[i].apply)example.steps[i].apply(s);}return s;}
function reached(s){const done=new Set();const work=[s.root];while(work.length){const k=work.pop();if(k===null||k===undefined||done.has(k))continue;done.add(k);const n=s.nodes[k];if(n){work.push(n.l,n.r);}}return done;}
function svg(tag,attrs,text){const el=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,v);if(text!==undefined)el.textContent=String(text);return el;}
function empty(el){el.replaceChildren();return el;}
function line(g,a,b,color,dashed,width){const l=svg('line',{x1:a[0],y1:a[1],x2:b[0],y2:b[1],stroke:color,'stroke-width':width||3,'stroke-dasharray':dashed?'8 6':'none','stroke-linecap':'round'});g.appendChild(l);}
function nodeCircle(g,x,y,k,role,isAttached){let color=role==='z'?'#2563eb':role==='y'?'#d97706':'#839db7',fill=role==='z'?'#dbeafe':role==='y'?'#ffebcf':'#fff';if(!isAttached){color=role==='y'?'#e49b31':'#a8b5c3';fill=role==='y'?'#fff5e5':'#eef2f6'}const node=svg('g',{'data-node':k,tabindex:'0',role:'button','aria-label':'Node '+k});node.appendChild(svg('circle',{cx:x,cy:y,r:27,fill,stroke:color,'stroke-width':2.5,'stroke-dasharray':isAttached?'none':'5 4'}));node.appendChild(svg('text',{x,y:y+7,'text-anchor':'middle','font-size':21,'font-weight':'700',fill:'#183149','pointer-events':'none'},k));node.addEventListener('click',()=>{selected=k;inspect();});node.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selected=k;inspect();}});g.appendChild(node);}
function inspect(){const data=examples[mode],s=snapshot(data,step),r=reached(s),info=document.getElementById('inspect');if(selected===null){info.textContent='点击图中任何 Node，查看它当前的 left / right / p。';return;}const n=s.nodes[selected];const fmt=v=>v===null?'null':String(v);info.textContent=`Node ${selected} ${r.has(selected)?'（当前属于 BST）':'（脱离主树）'}　left=${fmt(n.l)}　right=${fmt(n.r)}　p=${fmt(n.p)}`;}
function render(){const e=examples[mode],meta=e.steps[step],s=snapshot(e,step),reachable=reached(s),xy=e.positions(step);
 const edgeG=empty(document.getElementById('links')),nodeG=empty(document.getElementById('nodes')),labelG=empty(document.getElementById('labels')),bgG=empty(document.getElementById('background'));
 bgG.appendChild(svg('text',{x:20,y:29,fill:'#688199','font-size':16},'实线 = 当前 BST   ·   虚线 = 暂时脱离主树'));
 // Draw main-tree child references, and dashed detached-only references; ignore stale references crossing to main tree.
 for(const [key,n] of Object.entries(s.nodes)){
 const k=+key;
 for(const child of [n.l,n.r]){
 if(child===null)continue;
 const sourceIn=reachable.has(k),destIn=reachable.has(child);
 if(sourceIn===destIn){const changed=(mode==='direct'&&step===4&&k===30&&child===10)||(mode==='deep'&&step===2&&k===40&&child===27)||(mode==='deep'&&step===6&&k===25&&child===10);
 line(edgeG,xy[k],xy[child],!sourceIn?'#d5a461':changed?'#17a475':'#98abc0',!sourceIn,changed?4.4:3);}
 }
 }
 if(mode==='deep'&&step===3||mode==='deep'&&step===4){ // Separate temporary link y.right -> original right subtree.
 line(edgeG,xy[25],xy[40],'#d5a461',true,2.2);
 }
 for(const key of Object.keys(s.nodes)){
 const k=+key,[x,y]=xy[k],role=k===e.z?'z':k===e.y?'y':'other';nodeCircle(nodeG,x,y,k,role,reachable.has(k));
 if(k===e.z&&reachable.has(k))labelG.appendChild(svg('text',{x,y:y-35,'text-anchor':'middle',fill:'#2865a8','font-weight':700,'font-size':16},'z'));
 if(k===e.y)labelG.appendChild(svg('text',{x,y:y-35,'text-anchor':'middle',fill:'#b36a1a','font-weight':700,'font-size':16},reachable.has(k)&&step>=3?'y · root':'y'));
 }
 if(step>0){const old=e.z;if(!reachable.has(old)){const [x,y]=xy[old];labelG.appendChild(svg('text',{x,y:y+43,'text-anchor':'middle',fill:'#758698','font-size':12},'detached z'));}}
 const sub=document.getElementById('subtitle');sub.textContent=e.sub;
 document.getElementById('stepTitle').textContent=meta.title;
 document.getElementById('desc').textContent=meta.desc;
 document.getElementById('change').textContent=meta.change;
 document.getElementById('calls').textContent=`${meta.calls} / ${mode==='direct'?1:2}`;
 document.getElementById('rootInfo').textContent=`root=${s.root} · y=${e.y}`;
 document.getElementById('counter').textContent=`Step ${step+1} / ${e.steps.length}`;
 const code=empty(document.getElementById('code'));
 for(let i=0;i<method.length;i++){
 const row=document.createElement('div');const skipped=mode==='direct'&&step>=2&&[8,9,10].includes(i);row.className='line'+(i===meta.line?' active':'')+(skipped?' skipped':'');
 const n=document.createElement('span');n.className='no';n.textContent=String(i+1).padStart(2,'0');
 const m=document.createElement('span');m.className='mark';m.textContent=i===meta.line?'▶':'';
 row.append(n,m,document.createTextNode(method[i]));code.appendChild(row);
 }
 document.getElementById('prev').disabled=step===0;
 document.getElementById('next').disabled=step===e.steps.length-1;
 document.getElementById('reset').disabled=step===0;
 const slider=document.getElementById('slider');slider.max=e.steps.length-1;slider.value=step;
 document.getElementById('tab-direct').setAttribute('aria-selected',String(mode==='direct'));
 document.getElementById('tab-deep').setAttribute('aria-selected',String(mode==='deep'));
 inspect();
 }
 function changeMode(x){mode=x;step=0;selected=null;render();}
 document.getElementById('tab-direct').addEventListener('click',()=>changeMode('direct'));
 document.getElementById('tab-deep').addEventListener('click',()=>changeMode('deep'));
 document.getElementById('prev').addEventListener('click',()=>{step=Math.max(0,step-1);render();});
 document.getElementById('next').addEventListener('click',()=>{step=Math.min(step+1,examples[mode].steps.length-1);render();});
 document.getElementById('reset').addEventListener('click',()=>{step=0;selected=null;render();});
 document.getElementById('slider').addEventListener('input',e=>{step=+e.target.value;render();});
 document.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement||e.target instanceof HTMLButtonElement)return;if(e.key==='ArrowRight'){step=Math.min(step+1,examples[mode].steps.length-1);render();}if(e.key==='ArrowLeft'){step=Math.max(step-1,0);render();}});
 render();
})();
</script>
</body>
</html>
```

- **Direct**：`y == z.right` → 跳过 Deep 的 `if (y.p != z)` 分支 → `transplant(z, y)` → 接回 Left Subtree → `y.left.p = y`；共 7 步，1 次 Transplant
- **Deep**：`y.p != z` → `transplant(y, y.right)` 取出 y → `y.right = z.right` / `y.right.p = y` → `transplant(z,y)` → 接回 Left Subtree；共 8 步，2 次 Transplant
- 顶部 **Direct / Deep** Tab 切换；**Previous / Next / Reset / Slider** 控制；Tree 逐步变化，Java 对应行高亮；**点击任意 Node 可查看当步的 `left / right / p`**。使用 Child Reference 的连线，代码中间状态不强行当作完成的 BST。

**复现 Prompt**：读取已保存的 `content/interactive/bst-delete-direct-deep-interactive.html` 完整源码，保留 Direct / Deep 两个 Tab、对应的 7/8 Steps、Tree 动态位置、Java 当前行高亮、Parent Pointer/Child Reference 变化、节点点击检查、上一/下一步、Slider 和 Reset。Direct 初始 `20(10(5,15),30(-,40))`；Deep 初始 `20(10,40(25(-,27),50))`。特别保留 Deep 的第一次 `transplant(y,y.right)`、更新右子树、第二次 `transplant(z,y)`、接回左子树的逐行执行过程。**禁止使用 Image Generation，不得替换为静态图片。**

